      "path": "packages/plugin-notes/src/service.ts",
      "content": "/**\n * ctx.notes：把 notes 域的 KvTable 封装成便签 CRUD；读取同步（storage-domain 权威内存态），写入经后端持久化后生效。\n *\n * Typert Remote 服务（SRC 标记，无 codegen）：端点参数 wire 名 = 方法形参名，所以方法\n * 签名不得解构参数，client 侧 descriptors 的 wire 名必须与之完全一致。\n */\n\nimport { randomUUID } from 'node:crypto'\nimport { TypertRemoteService } from '@deepseek-ai/dsh-typert-protocol'\nimport type { Context } from '@deepseek-ai/cordis'\nimport { brandString } from '@deepseek-ai/dsh-brand'\nimport { bridgeWaiting, type NotesAgentBridgeState } from './agent/bridge-state.ts'\nimport type { Domain, KvTable } from '@deepseek-ai/dsh-storage-domain'\nimport type { notesDomain } from './domain.ts'\nimport type { TaskLease } from './domain.ts'\nimport { DEFAULT_NOTE_COLOR } from './types.ts'\nimport type {\n  NoteCreateInput,\n  NoteId,\n  NoteLane,\n  NoteModelSelection,\n  NoteRecord,\n  NoteSchedule,\n  NoteUpdateInput,\n  TaskStatus,\n  TaskTargets,\n} from './types.ts'\nimport { applyRunResult, armSchedule } from './schedule.ts'\nimport type {\n  WebdavBackupResult,\n  WebdavListResult,\n  WebdavRestoreResult,\n  WebdavStatus,\n} from './types.ts'\nimport type { WebdavRunner } from './webdav-backup.ts'\nimport { beginRun, settleRun } from './client/core/task-lanes.ts'\n\n/** notes/watch 流推送的变更事件。 */\nexport interface NotesChangeEvent {\n  readonly changedAt: number\n}\n\n/** 任务执行事务结果，client 只当不透明值透传。 */\nexport type TaskExecuteResult =\n  | { readonly ok: true; readonly note: NoteRecord }\n  | {\n      readonly ok: false\n      readonly reason: 'missing' | 'busy' | 'missing-workspace' | 'no-dispatch' | 'dispatch-failed'\n    }\n\ntype NotesChangeListener = () => void\n\n/** 空串 / undefined 都表示「用宿主默认」，不落空字段。 */\nfunction makeTaskLane(\n  status: TaskStatus,\n  agentPreset: string | undefined,\n  model: NoteModelSelection | undefined,\n): NoteLane {\n  const preset = agentPreset?.trim() ?? ''\n  return {\n    status,\n    ...(preset !== '' ? { agentPreset: preset } : {}),\n    ...(model !== undefined ? { model } : {}),\n  }\n}\n\n/**\n * 任务执行运行时（host 注入；见 agent/task-dispatch.ts）。\n * 拆成四个成员是为了把「新建会话」与「投递」分成两相：租约在两相之间落地，\n * 不存在 prompt 已投出但租约未写的竞态。\n */\nexport interface NotesTaskRuntime {\n  /** 新建执行会话（cwd = workspace）；失败抛错。给 `agentPreset` 即按该预设装配。 */\n  createSession(input: {\n    readonly workspace: string\n    readonly agentPreset?: string\n  }): Promise<string>\n  /** 必须在投递 prompt 之前调用，首个 turn 才用得上模型；失败抛错。 */\n  selectModel(input: {\n    readonly sessionId: string\n    readonly model: NoteModelSelection\n  }): Promise<void>\n  /** 向执行会话投递任务 prompt（agent 由此开工）。 */\n  prompt(input: {\n    readonly noteId: NoteId\n    readonly title: string\n    readonly sessionId: string\n    readonly workspace: string\n  }): Promise<void>\n  /** 工作区候选（最近会话用过的 cwd，供 UI 下拉）；失败 / 不可用返回空数组。 */\n  listWorkspaces(): Promise<readonly string[]>\n  /** 宿主缺能力 / 查询失败一律返回空目录，绝不抛。 */\n  listTaskTargets(): Promise<TaskTargets>\n}\n\nexport interface NotesServiceConfig {\n  readonly domain: Domain<typeof notesDomain>\n  /** 未注入时 taskExecute 在任何状态变更前直接返回 no-dispatch。 */\n  readonly task?: NotesTaskRuntime\n  /** 缺省时 webdav* 端点返回结构化失败，不炸端点。 */\n  readonly webdav?: WebdavRunner\n}\n\nexport class NotesService extends TypertRemoteService {\n  private readonly table: KvTable<NoteId, NoteRecord>\n  private readonly leases: KvTable<NoteId, TaskLease>\n  private readonly task: NotesServiceConfig['task']\n  private readonly webdav: NotesServiceConfig['webdav']\n  /** 默认 waiting：tools 服务出现后由 index.ts 推进为 installed/failed。 */\n  private agentBridge: NotesAgentBridgeState = bridgeWaiting()\n  /** notes/watch 每个打开的客户端流一个订阅者。 */\n  private readonly changeListeners = new Set<NotesChangeListener>()\n\n  constructor(ctx: Context, config: NotesServiceConfig) {\n    super(ctx, 'notes')\n    this.table = config.domain.table('notes')\n    this.leases = config.domain.table('leases')\n    this.task = config.task\n    this.webdav = config.webdav\n  }\n\n  getAgentBridgeState(): NotesAgentBridgeState {\n    return this.agentBridge\n  }\n\n  /** 只给 host 的桥装配器用，不在 markRemoteMethods 白名单里。 */\n  setAgentBridgeState(next: NotesAgentBridgeState): void {\n    this.agentBridge = next\n  }\n\n  list(): NoteRecord[] {\n    return Array.from(this.table.entries(), ([, note]) => note)\n  }\n\n  /**\n   * notes/watch 流端点。写入成功广播一次，事件只带时间戳，client 收到自行 list()。\n   * signal 与等待做 race：consumer 断开时等待立即结算，不留悬置 await 卡住 return()。\n   */\n  async *watch(signal?: AbortSignal): AsyncGenerator<NotesChangeEvent> {\n    const lifetime = signal ?? new AbortController().signal\n    if (lifetime.aborted) return\n    let resolveWaiter: ((reason: 'event' | 'abort') => void) | undefined\n    const wake = (): void => {\n      const resolve = resolveWaiter\n      resolveWaiter = undefined\n      if (resolve !== undefined) resolve('event')\n    }\n    const onAbort = (): void => {\n      const resolve = resolveWaiter\n      resolveWaiter = undefined\n      if (resolve !== undefined) resolve('abort')\n    }\n    this.changeListeners.add(wake)\n    lifetime.addEventListener('abort', onAbort, { once: true })\n    try {\n      while (true) {\n        if (resolveWaiter === undefined) {\n          const reason = await new Promise<'event' | 'abort'>((resolve) => { resolveWaiter = resolve })\n          if (reason === 'abort') return\n        }\n        yield { changedAt: Date.now() }\n      }\n    } finally {\n      this.changeListeners.delete(wake)\n      lifetime.removeEventListener('abort', onAbort)\n    }\n  }\n\n  /** 广播一次变更（幂等安全；订阅者抛错不扩散）。 */\n  private broadcastChanged(): void {\n    for (const listener of [...this.changeListeners]) {\n      try {\n        listener()\n      } catch (error) {\n        // 订阅者抛错只丢该条，不炸写操作。\n        console.error('[plugin-notes] change listener failed:', error)\n      }\n    }\n  }\n\n  async create(input: NoteCreateInput): Promise<NoteRecord> {\n    const now = Date.now()\n    const schedule = input.schedule !== undefined ? armSchedule(input.schedule, now) : undefined\n    if (input.schedule !== undefined && schedule === undefined) {\n      throw new Error(`schedule 参数非法：mode=${input.schedule.mode} 缺少必填字段`)\n    }\n    const note: NoteRecord = {\n      id: brandString<NoteId>(randomUUID()),\n      title: input.title?.trim() || '新便签',\n      text: input.text,\n      pinned: false,\n      archived: false,\n      color: input.color ?? DEFAULT_NOTE_COLOR,\n      origin: input.origin ?? 'user',\n      // 缺省不落 lane：普通便签不进泳道。\n      ...(input.laneStatus !== undefined\n        ? { lane: makeTaskLane(input.laneStatus, input.agentPreset, input.model) }\n        : {}),\n      ...(input.workspace !== undefined && input.workspace.trim() !== ''\n        ? { workspace: input.workspace.trim() }\n        : {}),\n      ...(input.dueAt !== undefined ? { dueAt: input.dueAt } : {}),\n      // 只有任务便签才落 schedule，调度器不认无 lane 的日程。\n      ...(input.laneStatus !== undefined && schedule !== undefined ? { schedule } : {}),\n      createdAt: now,\n      updatedAt: now,\n    }\n    await this.table.put(note.id, note)\n    this.broadcastChanged()\n    return note\n  }\n\n  /** 缺省字段保持原值；`origin` 不可更新。 */\n  async update(id: NoteId, patch: NoteUpdateInput): Promise<NoteRecord | undefined> {\n    const current = this.table.get(id)\n    if (!current) return undefined\n    const now = Date.now()\n    // lane patch：逐字段合并；run 提供即整体替换；空 patch = no-op（不凭空造 lane）。\n    // `clear: true` 优先于 status/run，移除任务身份即手动接管。\n    let lane: NoteLane | undefined = current.lane\n    if (patch.lane?.clear === true) {\n      lane = undefined\n    } else if (patch.lane !== undefined && (patch.lane.status !== undefined || patch.lane.run !== undefined)) {\n      const status: TaskStatus | undefined = patch.lane.status ?? current.lane?.status\n      // 无 lane 时仅凭 run 会拼出没有 status 的 lane，schema 校验会让下次打开直接炸库。\n      if (status === undefined) {\n        throw new Error('lane patch 缺 status：便签无 lane 时须同时提供 status，不能仅凭 run 造 lane')\n      }\n      // 给值即覆盖，空串 / null 即清除回宿主默认。\n      const agentPreset: string | undefined =\n        patch.lane.agentPreset === undefined\n          ? current.lane?.agentPreset\n          : patch.lane.agentPreset.trim() !== ''\n            ? patch.lane.agentPreset.trim()\n            : undefined\n      const model: NoteModelSelection | undefined =\n        patch.lane.model === undefined ? current.lane?.model : (patch.lane.model ?? undefined)\n      lane = {\n        ...current.lane,\n        status,\n        ...(patch.lane.run !== undefined ? { run: patch.lane.run } : {}),\n        ...(agentPreset !== undefined ? { agentPreset } : {}),\n        ...(model !== undefined ? { model } : {}),\n      }\n    }\n    // 改到不同状态且当前 run 帧还开着时，先把该帧收尾为「用户手动接管」；\n    // 否则 run.finishedAt 缺失会让 client 误以为仍在执行、编辑器一直锁着。\n    const statusChanged = patch.lane?.status !== undefined && patch.lane.status !== current.lane?.status\n    const currentRunOpen = current.lane?.run !== undefined && current.lane.run.finishedAt === undefined\n    if (statusChanged && currentRunOpen) {\n      const settled = settleRun(current.lane!, false, '用户手动接管', now)\n      lane = { ...lane!, run: settled.run }\n    }\n    // 必须先剥离旧 lane / workspace，否则取消任务后旧值会随 ...current 残留。\n    // workspace 给值即覆盖，trim 后空串 = 清除回设置默认。\n    const workspace: string | undefined =\n      patch.workspace === undefined\n        ? current.workspace\n        : patch.workspace.trim() !== ''\n          ? patch.workspace.trim()\n          : undefined\n    // schedule：null = 清除；给对象即整体替换，但保留宿主已记的最近派发信息。\n    let schedule: NoteSchedule | undefined = current.schedule\n    if (patch.schedule === null) {\n      schedule = undefined\n    } else if (patch.schedule !== undefined) {\n      const armed = armSchedule({ ...current.schedule, ...patch.schedule }, now)\n      if (armed === undefined) {\n        throw new Error(`schedule 参数非法：mode=${patch.schedule.mode} 缺少必填字段`)\n      }\n      schedule = armed\n    }\n    if (lane === undefined) schedule = undefined\n    const dueAt: number | undefined =\n      patch.dueAt === undefined ? current.dueAt : (patch.dueAt ?? undefined)\n    const { lane: _currentLane, schedule: _currentSchedule, workspace: _currentWorkspace, dueAt: _currentDueAt, ...currentWithoutLane } = current\n    const next: NoteRecord = {\n      ...currentWithoutLane,\n      ...(patch.title !== undefined ? { title: patch.title } : {}),\n      ...(patch.text !== undefined ? { text: patch.text } : {}),\n      ...(patch.pinned !== undefined ? { pinned: patch.pinned } : {}),\n      archived: patch.archived ?? current.archived ?? false,\n      color: patch.color ?? current.color ?? DEFAULT_NOTE_COLOR,\n      // origin 一经创建不可改写。\n      origin: current.origin ?? 'user',\n      updatedAt: now,\n      ...(workspace !== undefined ? { workspace } : {}),\n      ...(dueAt !== undefined ? { dueAt } : {}),\n      ...(lane !== undefined ? { lane } : {}),\n      ...(schedule !== undefined ? { schedule } : {}),\n    }\n    // 用户侧改状态 / 取消任务 / 归档即接管，撤销租约；同状态不算。\n    if (\n      patch.lane?.clear === true ||\n      (patch.lane?.status !== undefined && patch.lane.status !== current.lane?.status) ||\n      patch.archived === true\n    ) {\n      await this.revokeTaskLease(id)\n    }\n    await this.table.put(id, next)\n    this.broadcastChanged()\n    return next\n  }\n\n  async setPinned(id: NoteId, pinned: boolean): Promise<NoteRecord | undefined> {\n    const current = this.table.get(id)\n    if (!current) return undefined\n    const next: NoteRecord = {\n      ...current,\n      pinned,\n      color: current.color ?? DEFAULT_NOTE_COLOR,\n      updatedAt: Date.now(),\n    }\n    await this.table.put(id, next)\n    return next\n  }\n\n  /** 删除前先撤销执行租约。 */\n  async delete(id: NoteId): Promise<boolean> {\n    await this.revokeTaskLease(id)\n    const deleted = await this.table.delete(id)\n    if (deleted) this.broadcastChanged()\n    return deleted\n  }\n\n  /**\n   * 写 leases 行 + 置 lane running + 新 run 帧（重跑时新帧覆盖旧帧）。\n   * 'busy' = 无 lane 或已有 active lease（防双跑）。host 内部方法，不经 remote 暴露。\n   */\n  async grantTaskLease(\n    id: NoteId,\n    sessionId: string,\n    by: 'user' | 'schedule' = 'user',\n  ): Promise<'granted' | 'missing' | 'busy'> {\n    const note = this.table.get(id)\n    if (!note) return 'missing'\n    if (!note.lane || this.leases.get(id)) return 'busy'\n    const now = Date.now()\n    await this.leases.put(id, { noteId: id, sessionId, grantedAt: now })\n    // run.by 供 host 超时兜底认领定时发起的那些。\n    await this.table.put(id, { ...note, lane: beginRun(note.lane, now, by), updatedAt: now })\n    this.broadcastChanged()\n    return 'granted'\n  }\n\n  /** 只给 host 调度器：直写 schedule。不走 update，避免触发「改状态即接管」撤销租约。 */\n  async setSchedule(id: NoteId, schedule: NoteSchedule | undefined): Promise<NoteRecord | undefined> {\n    const current = this.table.get(id)\n    if (!current) return undefined\n    const { schedule: _previous, ...rest } = current\n    const now = Date.now()\n    const next: NoteRecord = { ...rest, ...(schedule !== undefined ? { schedule } : {}), updatedAt: now }\n    await this.table.put(id, next)\n    this.broadcastChanged()\n    return next\n  }\n\n  /** 只删 leases 行，不改 lane —— 状态由调用方决定。 */\n  async revokeTaskLease(id: NoteId): Promise<boolean> {\n    return this.leases.delete(id)\n  }\n\n  getTaskLease(id: NoteId): TaskLease | undefined {\n    return this.leases.get(id)\n  }\n\n  /**\n   * agent 工具专用。只允许置 running：完成 / 失败是 notes_task_report 的职责。\n   * 直写内存表不经 update，避开「手动改状态即撤销租约」的钩子（agent 写 lane 由 lease 授权）。\n   */\n  async setTaskStatus(id: NoteId, status: TaskStatus): Promise<NoteRecord | undefined> {\n    if (status !== 'running') {\n      throw new Error('任务状态变更请用执行中的 report 结束：set_status 仅允许置为 running')\n    }\n    const current = this.table.get(id)\n    if (!current?.lane) return undefined\n    const now = Date.now()\n    const lane: NoteLane =\n      current.lane.run === undefined\n        ? beginRun(current.lane, now)\n        : { ...current.lane, status }\n    const next: NoteRecord = { ...current, lane, updatedAt: now }\n    await this.table.put(id, next)\n    this.broadcastChanged()\n    return next\n  }\n\n  /**\n   * agent 工具专用：settleRun 补 finishedAt/ok/summary，status 置 done/failed，撤销 lease。\n   * 循环日程例外：状态落回 'todo'，等下一周期再派发。\n   */\n  async settleTaskRun(id: NoteId, ok: boolean, summary: string): Promise<NoteRecord | undefined> {\n    const current = this.table.get(id)\n    if (!current?.lane) return undefined\n    const now = Date.now()\n    const looping = current.schedule?.enabled === true && current.schedule.mode !== 'once'\n    const status: TaskStatus = looping ? 'todo' : ok ? 'done' : 'failed'\n    const lane: NoteLane = { ...settleRun(current.lane, ok, summary, now), status }\n    await this.revokeTaskLease(id)\n    // 成败写回日程的失败连击：成功清零、失败累加，到上限自动停用。\n    const schedule = current.schedule !== undefined ? applyRunResult(current.schedule, ok, now) : undefined\n    const next: NoteRecord = {\n      ...current,\n      lane,\n      ...(schedule !== undefined ? { schedule } : {}),\n      updatedAt: now,\n    }\n    await this.table.put(id, next)\n    this.broadcastChanged()\n    return next\n  }\n\n  /**\n   * 执行事务：按工作区新建会话 → 选模型 → 授权租约 → 投递 prompt。\n   * 工作区只看便签自己的 workspace，没有就是 missing-workspace（不新建会话、不改状态）。\n   * 回滚 = revokeTaskLease + 直写恢复快照 lane（不经 update，避开接管钩子）。\n   */\n  async taskExecute(id: NoteId): Promise<TaskExecuteResult> {\n    return this.runTaskExecute(id, 'user')\n  }\n\n  /** 只给 host 调度器：同一条事务，只是 run 帧标 by='schedule'，白名单不含它。 */\n  async taskExecuteScheduled(id: NoteId): Promise<TaskExecuteResult> {\n    return this.runTaskExecute(id, 'schedule')\n  }\n\n  /** 两个入口共用的本体：by 写进 run 帧。 */\n  private async runTaskExecute(id: NoteId, by: 'user' | 'schedule'): Promise<TaskExecuteResult> {\n    const current = this.table.get(id)\n    if (!current) return { ok: false, reason: 'missing' }\n    // 归档便签不得执行。\n    if (current.archived || !current.lane || this.leases.get(id)) {\n      return { ok: false, reason: 'busy' }\n    }\n    // 先于工作区解析判定：没有运行时就该报 no-dispatch。\n    if (this.task === undefined) return { ok: false, reason: 'no-dispatch' }\n    const workspace = (current.workspace ?? '').trim()\n    if (workspace === '') return { ok: false, reason: 'missing-workspace' }\n    const snapshot = current\n\n    let sessionId: string\n    try {\n      sessionId = await this.task.createSession({\n        workspace,\n        ...(current.lane.agentPreset !== undefined ? { agentPreset: current.lane.agentPreset } : {}),\n      })\n    } catch {\n      return { ok: false, reason: 'dispatch-failed' }\n    }\n\n    // 必须在投递前选好，第一个 turn 才用得上。\n    if (current.lane.model !== undefined) {\n      try {\n        await this.task.selectModel({ sessionId, model: current.lane.model })\n      } catch {\n        return { ok: false, reason: 'dispatch-failed' }\n      }\n    }\n\n    const granted = await this.grantTaskLease(id, sessionId, by)\n    if (granted !== 'granted') {\n      return { ok: false, reason: granted === 'missing' ? 'missing' : 'busy' }\n    }\n\n    try {\n      await this.task.prompt({ noteId: id, title: current.title, sessionId, workspace })\n    } catch {\n      await this.rollbackTaskExecute(id, snapshot)\n      return { ok: false, reason: 'dispatch-failed' }\n    }\n\n    const fresh = this.table.get(id)\n    if (!fresh) return { ok: false, reason: 'missing' }\n    return { ok: true, note: fresh }\n  }\n\n  /** 运行时缺省或查询失败一律空数组，纯 UI 宿主不炸端点。 */\n  async listWorkspaces(): Promise<readonly string[]> {\n    if (this.task === undefined) return []\n    try {\n      return await this.task.listWorkspaces()\n    } catch {\n      return []\n    }\n  }\n\n  /** 缺省 / 查询抛错一律空目录，编辑器据此只显示「宿主默认」。 */\n  async taskTargets(): Promise<TaskTargets> {\n    if (this.task === undefined) return { models: [], presets: [] }\n    try {\n      return await this.task.listTaskTargets()\n    } catch {\n      return { models: [], presets: [] }\n    }\n  }\n\n  /** 手动接管：撤销租约 + settleRun(false) + 状态置 'todo'，直写不经 update。 */\n  async taskReset(id: NoteId): Promise<{ ok: true; note: NoteRecord } | { ok: false }> {\n    const current = this.table.get(id)\n    if (!current?.lane) return { ok: false }\n    await this.revokeTaskLease(id)\n    const now = Date.now()\n    const lane: NoteLane = { ...settleRun(current.lane, false, '用户手动接管', now), status: 'todo' }\n    const next: NoteRecord = { ...current, lane, updatedAt: now }\n    await this.table.put(id, next)\n    this.broadcastChanged()\n    return { ok: true, note: next }\n  }\n\n  /** 删 lease 行 + 直写恢复 grant 前的整张便签。 */\n  private async rollbackTaskExecute(id: NoteId, snapshot: NoteRecord): Promise<void> {\n    await this.revokeTaskLease(id)\n    await this.table.put(id, snapshot)\n    this.broadcastChanged()\n  }\n\n  async webdavBackup(): Promise<WebdavBackupResult> {\n    if (this.webdav === undefined) return { ok: false, reason: 'WebDAV 引擎未装配' }\n    return this.webdav.backupNow()\n  }\n\n  /** desc 时间序，仅本插件命名。 */\n  async webdavList(): Promise<WebdavListResult> {\n    if (this.webdav === undefined) return { ok: false, reason: 'WebDAV 引擎未装配' }\n    return this.webdav.listFiles()\n  }\n\n  /** `'latest'` = 最近一份。 */\n  async webdavRestore(name: string): Promise<WebdavRestoreResult> {\n    if (this.webdav === undefined) return { ok: false, reason: 'WebDAV 引擎未装配' }\n    return this.webdav.restore(name)\n  }\n\n  async webdavStatus(): Promise<WebdavStatus> {\n    if (this.webdav === undefined) {\n      return {\n        enabled: false,\n        lastBackupAt: null,\n        lastBackupOk: null,\n        lastBackupError: null,\n        lastBackupName: null,\n        lastRestoreAt: null,\n        lastRestoreOk: null,\n        lastRestoreName: null,\n      }\n    }\n    return this.webdav.status()\n  }\n\n  /** 清空便签与租约两表后按 payload 逐条写入，只给 host 的 WebDAV 恢复流程用。 */\n  async replaceAll(notes: readonly NoteRecord[]): Promise<void> {\n    for (const [id] of this.table.entries()) await this.table.delete(id)\n    for (const [leaseId] of this.leases.entries()) await this.leases.delete(leaseId)\n    for (const note of notes) await this.table.put(note.id, note)\n    this.broadcastChanged()\n  }\n}\n\n/** 手工复刻 @Remote 装饰器产物，避免构建依赖标准装饰器转译。 */\nconst REMOTE_METHODS = '@deepseek-ai/dsh-typert-protocol/remote-methods'\n\ntype RemoteMethodEntry =\n  | { readonly method: string; readonly mode?: undefined }\n  | { readonly method: string; readonly mode: 'stream' }\n\nfunction markRemoteMethods(prototype: object, methods: readonly RemoteMethodEntry[]): void {\n  Object.defineProperty(prototype, REMOTE_METHODS, {\n    configurable: true,\n    value: Object.freeze({\n      version: 1,\n      methods: Object.freeze(\n        methods.map((entry) =>\n          Object.freeze({\n            method: entry.method,\n            ...(entry.mode !== undefined ? { mode: entry.mode } : {}),\n            invocation: Object.freeze({ kind: 'direct' as const }),\n          }),\n        ),\n      ),\n    }),\n  })\n}\n\nmarkRemoteMethods(NotesService.prototype, [\n  { method: 'list' },\n  { method: 'create' },\n  { method: 'update' },\n  { method: 'setPinned' },\n  { method: 'delete' },\n  { method: 'getAgentBridgeState' },\n  { method: 'taskExecute' },\n  { method: 'listWorkspaces' },\n  { method: 'taskTargets' },\n  { method: 'taskReset' },\n  { method: 'watch', mode: 'stream' },\n  { method: 'webdavBackup' },\n  { method: 'webdavList' },\n  { method: 'webdavRestore' },\n  { method: 'webdavStatus' },\n])\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Context {\n    notes: NotesService\n  }\n}\n"
    },
    {
      "path": "packages/plugin-notes/src/agent/tools.ts",
      "content": "/**\n * 便签 agent 工具：读工具放行，碰 origin='user' 便签的写工具由工具自身走\n * user-questions 问一次同意（不经 approval seam，与会话审批策略无关）；\n * 宿主没有该 seam 时 guard 兜底禁删。\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { ToolExecution } from '@deepseek-ai/dsh-tools'\nimport type {} from '@deepseek-ai/dsh-user-approval'\nimport type {} from '../service.ts'\nimport type { NoteId, NoteRecord, TaskStatus } from '../types.ts'\nimport { NOTE_COLORS } from '../types.ts'\n\nexport const NOTES_TOOL_PREFIX = 'notes_'\n\nconst TOOL_LIST = `${NOTES_TOOL_PREFIX}list`\nconst TOOL_GET = `${NOTES_TOOL_PREFIX}get`\nconst TOOL_CREATE = `${NOTES_TOOL_PREFIX}create`\nconst TOOL_UPDATE = `${NOTES_TOOL_PREFIX}update`\nconst TOOL_SET_PINNED = `${NOTES_TOOL_PREFIX}set_pinned`\nconst TOOL_DELETE = `${NOTES_TOOL_PREFIX}delete`\n\nconst TOOL_TASK_SET_STATUS = `${NOTES_TOOL_PREFIX}task_set_status`\nconst TOOL_TASK_REPORT = `${NOTES_TOOL_PREFIX}task_report`\n\nconst WRITE_TOOLS = new Set<string>([TOOL_CREATE, TOOL_UPDATE, TOOL_SET_PINNED, TOOL_DELETE])\n\nexport function isNotesTool(name: string): boolean {\n  return name.startsWith(NOTES_TOOL_PREFIX)\n}\n\nexport function isNotesWriteTool(name: string): boolean {\n  return WRITE_TOOLS.has(name)\n}\n\nfunction noteLabel(note: NoteRecord): string {\n  return note.title === '' ? note.id : note.title\n}\n\nfunction noteById(ctx: Context, id: unknown): NoteRecord | undefined {\n  if (typeof id !== 'string') return undefined\n  return ctx.notes.list().find((n) => n.id === id)\n}\n\n/** 只为 Context 声明合并，让 ctx.get('userQuestions') 的类型成立（type-only）。 */\nimport type {} from '@deepseek-ai/dsh-user-questions'\n\nconst CONSENT_ALLOW = '允许一次'\nconst CONSENT_DENY = '不要'\n\n/**\n * 由工具自身走 user-questions 问一次同意，不经 approval seam，\n * 故与会话审批策略无关；没有该 seam 或未选中「允许一次」一律抛错。\n */\nexport async function requestNoteConsent(ctx: Context, exec: ToolExecution, action: string): Promise<void> {\n  const questions = ctx.get('userQuestions')\n  if (questions === undefined) {\n    throw new Error(`cannot ${action}: this host has no way to ask you for consent`)\n  }\n  let answer: Awaited<ReturnType<typeof questions.ask>>\n  try {\n    answer = await questions.ask({\n      questions: [{\n        id: 'notes-consent',\n        question: `The agent wants to ${action}. Allow?`,\n        options: [{ label: CONSENT_ALLOW }, { label: CONSENT_DENY }],\n      }],\n      ...exec.agent !== undefined ? { agent: exec.agent } : {},\n      ...exec.signal !== undefined ? { signal: exec.signal } : {},\n    })\n  } catch (error) {\n    throw new Error(`cannot ${action}: the confirmation could not be shown`, { cause: error })\n  }\n  const selected = answer.answers.find(a => a.id === 'notes-consent')?.selected ?? []\n  if (selected.includes(CONSENT_ALLOW)) return\n  throw new Error(`cannot ${action}: not allowed`)\n}\n\nexport function isNotesTaskTool(name: string): boolean {\n  return name === TOOL_TASK_SET_STATUS || name === TOOL_TASK_REPORT\n}\n\n/* ---------- 渲染（model-facing 文本） ---------- */\n\n/** 与 types.ts 的 TaskStatus 同步（此处写死字面量，避免运行时 import domain.ts）。 */\nconst TASK_STATUSES = ['backlog', 'todo', 'running', 'done', 'failed'] as const\n\n/** 与 types.ts 的 SCHEDULE_MODES 同步（同样写死字面量，避免运行时 import）。 */\nconst SCHEDULE_MODES = ['once', 'interval', 'daily', 'weekly', 'monthly'] as const\n\nfunction noteText(note: NoteRecord): string {\n  const flags = [\n    note.pinned ? 'pinned' : '',\n    note.archived ? 'archived' : '',\n    note.origin === 'agent' ? 'agent-created' : 'user-created',\n  ].filter(Boolean).join(', ')\n  const meta = flags.length > 0 ? `\\n(${flags})` : ''\n  const lane = note.lane\n  const laneLine = lane\n    ? `\\n(task: ${lane.status}` +\n      (lane.run ? ` · run@${lane.run.startedAt}` : '') +\n      (lane.run?.summary ? ` · ${lane.run.summary}` : '') +\n      ')'\n    : ''\n  return `${note.title || '(untitled)'}\\n${note.text || ''}${meta}${laneLine}`\n}\n\n/** 与 domain.ts 的 lane 校验一致。 */\nconst LANE_SCHEMA = {\n  type: 'object',\n  additionalProperties: false,\n  properties: {\n    status: { type: 'string', required: true, enum: [...TASK_STATUSES] },\n    run: {\n      type: 'object',\n      additionalProperties: false,\n      properties: {\n        startedAt: { type: 'number', required: true },\n        finishedAt: { type: 'number' },\n        ok: { type: 'boolean' },\n        summary: { type: 'string' },\n        by: { type: 'string', enum: ['user', 'schedule'] },\n      },\n    },\n    // 缺省 = 宿主默认预设 / 默认模型。\n    agentPreset: { type: 'string' },\n    model: {\n      type: 'object',\n      additionalProperties: false,\n      properties: {\n        provider: { type: 'string', required: true },\n        model: { type: 'string', required: true },\n        reasoningEffort: { type: 'string' },\n      },\n    },\n  },\n} as const\n\n/** 与 domain.ts 的 schedule 校验一致。 */\nconst SCHEDULE_SCHEMA = {\n  type: 'object',\n  additionalProperties: false,\n  properties: {\n    enabled: { type: 'boolean', required: true },\n    mode: { type: 'string', required: true, enum: [...SCHEDULE_MODES] },\n    at: { type: 'number' },\n    everyMin: { type: 'number' },\n    time: { type: 'string' },\n    weekdays: { type: 'array', items: { type: 'number' } },\n    monthDay: { type: 'number' },\n    endAt: { type: 'number' },\n    // nextAt 是权威下次时刻；failureStreak 达上限即熔断停用。\n    nextAt: { type: 'number', required: true },\n    lastFiredAt: { type: 'number' },\n    lastResult: { type: 'string' },\n    failureStreak: { type: 'number' },\n    runCount: { type: 'number' },\n  },\n} as const\n\n/**\n * 读/写工具的输出值都是整张 NoteRecord；输出校验是 additionalProperties:false，\n * 漏一个字段整次调用即判非法 —— 新增字段只改这一份。\n */\nconst NOTE_OUTPUT_SCHEMA = {\n  type: 'object',\n  additionalProperties: false,\n  properties: {\n    id: { type: 'string', required: true },\n    title: { type: 'string', required: true },\n    text: { type: 'string', required: true },\n    pinned: { type: 'boolean', required: true },\n    archived: { type: 'boolean', required: true },\n    color: { type: 'string', required: true, enum: [...NOTE_COLORS] },\n    origin: { type: 'string', required: true, enum: ['user', 'agent'] },\n    createdAt: { type: 'number', required: true },\n    updatedAt: { type: 'number', required: true },\n    lane: LANE_SCHEMA,\n    /** 缺省 = 不定时。 */\n    schedule: SCHEDULE_SCHEMA,\n    /** 绝对目录路径；缺省 = 执行被拒。 */\n    workspace: { type: 'string' },\n    dueAt: { type: 'number' },\n  },\n} as const\n\n/* ---------- guard（单调拒绝，同步） ---------- */\n\n/**\n * 仅兜底「宿主没装 user-questions seam」这一种情形：此时没有渠道征求同意，\n * 故拒绝删除 origin='user' 的便签。常规授权走 {@link requestNoteConsent}。\n */\nexport function notesDeleteGuard(ctx: Context, exec: ToolExecution): string | undefined {\n  if (exec.name !== TOOL_DELETE) return undefined\n  if (ctx.get('userQuestions') !== undefined) return undefined\n  const id = (exec.arguments as { note_id?: unknown } | undefined)?.note_id\n  if (typeof id !== 'string') return undefined\n  if (ctx.notes.list().find(n => n.id === id)?.origin !== 'user') return undefined\n  return `cannot delete note ${id}: it was written by the user (origin=user). Agents may only delete notes they created themselves (origin=agent).`\n}\n\n/**\n * 租约归属按 exec.agent.id 与会话比对（fail-closed：agent 缺省即拒）。\n * 便签不存在 / 无 lane / 无租约 / 会话不符都拒绝。\n */\nexport function notesTaskGuard(ctx: Context, exec: ToolExecution): string | undefined {\n  if (!isNotesTaskTool(exec.name)) return undefined\n  const args = exec.arguments as { note_id?: unknown } | undefined\n  const id = args?.note_id\n  if (typeof id !== 'string') return undefined\n  const note = ctx.notes.list().find((n) => n.id === id)\n  if (note === undefined) return `任务便签 ${id} 不存在`\n  if (note.lane === undefined) return `便签 ${id} 不是任务（无 lane），notes_task_* 只能操作任务便签`\n  const lease = ctx.notes.getTaskLease(id as NoteId)\n  if (lease === undefined) {\n    return `便签 ${id} 无有效执行租约：任务可能已被手动接管或已收尾，如需继续请重新执行`\n  }\n  const caller = exec.agent?.id\n  if (caller !== lease.sessionId) {\n    return `便签 ${id} 的执行租约属于会话 ${lease.sessionId}，与当前调用会话不符`\n  }\n  return undefined\n}\n\n/* ---------- 工具注册 ---------- */\n\nexport function installNotesTools(ctx: Context): void {\n  const notes = ctx.notes\n\n  /* ----- 读工具 ----- */\n\n  ctx.tools.register(defineTool({\n    name: TOOL_LIST,\n    description: 'List all sticky notes (id, title, color, pinned/archived flags). Use notes_get to read the full text of one note.',\n    parameters: {},\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          notes: {\n            type: 'array',\n            required: true,\n            items: NOTE_OUTPUT_SCHEMA,\n          },\n        },\n      },\n      render: (_args, value) => {\n        const items = (value as { notes: NoteRecord[] }).notes\n        if (items.length === 0) return [{ type: 'text', text: '(no notes)' }]\n        return [{\n          type: 'text',\n          text: items.map(n =>\n            `- ${n.id} · ${n.title || '(untitled)'}${n.archived ? ' · archived' : ''}${n.pinned ? ' · pinned' : ''} · ${n.color}`,\n          ).join('\\n'),\n        }]\n      },\n    },\n    async execute(_args, _exec) {\n      return { notes: notes.list() }\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: TOOL_GET,\n    description: 'Read one sticky note by id: full title and text plus its flags. The id comes from notes_list.',\n    parameters: {\n      note_id: { type: 'string', required: true, description: 'The note id from notes_list.' },\n    },\n    output: {\n      schema: NOTE_OUTPUT_SCHEMA,\n      render: (_args, value) => [{ type: 'text', text: noteText(value as NoteRecord) }],\n    },\n    async execute(args, _exec) {\n      const id = args.note_id as NoteId\n      const note = notes.list().find(n => n.id === id)\n      if (note === undefined) throw new Error(`note ${id} not found`)\n      return note\n    },\n  }))\n\n  /* ----- 写工具 ----- */\n\n  ctx.tools.register(defineTool({\n    name: TOOL_CREATE,\n    description:\n      'Create a sticky note. Notes created through this tool are marked origin=agent ' +\n      '(the user\\'s own notes are origin=user). Pass laneStatus to create it as a task note ' +\n      'sitting in that lane (task notes are the ones that can be dispatched to an agent); ' +\n      'omit it for a plain note.',\n    parameters: {\n      title: { type: 'string', description: 'Note title. Defaults to 新便签 when omitted.' },\n      text: { type: 'string', required: true, description: 'Note body (plain text or markdown).' },\n      color: { type: 'string', enum: [...NOTE_COLORS], description: 'Sticky-note color. Defaults to yellow when omitted.' },\n      laneStatus: { type: 'string', enum: [...TASK_STATUSES], description: 'Create it as a task note in this lane (Backlog / To do / Running / Done / Failed). Omit for a plain note.' },\n      dueAt: { type: 'number', description: 'Due date as epoch milliseconds (local midnight). Omit for unscheduled.' },\n    },\n    output: {\n      schema: NOTE_OUTPUT_SCHEMA,\n      render: (_args, value) => [{ type: 'text', text: noteText(value as NoteRecord) }],\n    },\n    async execute(args, _exec) {\n      return notes.create({\n        ...args.title !== undefined ? { title: args.title } : {},\n        text: args.text,\n        ...args.color !== undefined ? { color: args.color as NoteRecord['color'] } : {},\n        ...args.laneStatus !== undefined ? { laneStatus: args.laneStatus as TaskStatus } : {},\n        ...args.dueAt !== undefined ? { dueAt: args.dueAt } : {},\n        origin: 'agent',\n      })\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: TOOL_UPDATE,\n    description: 'Update an existing sticky note (title / text / color / pinned / archived). Only fields provided are changed; origin can never be changed. Updating a note the user wrote themselves asks them for confirmation first.',\n    parameters: {\n      note_id: { type: 'string', required: true, description: 'The note id from notes_list.' },\n      title: { type: 'string', description: 'New title.' },\n      text: { type: 'string', description: 'New body.' },\n      color: { type: 'string', enum: [...NOTE_COLORS], description: 'New color.' },\n      pinned: { type: 'boolean', description: 'Pin or unpin.' },\n      archived: { type: 'boolean', description: 'Archive or restore.' },\n      dueAt: { type: 'number', description: 'Due date as epoch milliseconds (local midnight). Pass 0 to clear it.' },\n    },\n    output: {\n      schema: NOTE_OUTPUT_SCHEMA,\n      render: (_args, value) => [{ type: 'text', text: noteText(value as NoteRecord) }],\n    },\n    async execute(args, exec) {\n      const id = args.note_id as NoteId\n      const target = noteById(ctx, id)\n      if (target?.origin === 'user') await requestNoteConsent(ctx, exec, `update your note \"${noteLabel(target)}\"`)\n      const note = await notes.update(id, {\n        ...args.title !== undefined ? { title: args.title } : {},\n        ...args.text !== undefined ? { text: args.text } : {},\n        ...args.color !== undefined ? { color: args.color as NoteRecord['color'] } : {},\n        ...args.pinned !== undefined ? { pinned: args.pinned } : {},\n        ...args.archived !== undefined ? { archived: args.archived } : {},\n        ...args.dueAt !== undefined ? { dueAt: args.dueAt > 0 ? args.dueAt : null } : {},\n      })\n      if (note === undefined) throw new Error(`note ${id} not found`)\n      return note\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: TOOL_SET_PINNED,\n    description: 'Pin or unpin one sticky note (equivalent to notes_update with only the pinned field).',\n    parameters: {\n      note_id: { type: 'string', required: true, description: 'The note id from notes_list.' },\n      pinned: { type: 'boolean', required: true, description: 'true pins, false unpins.' },\n    },\n    output: {\n      schema: NOTE_OUTPUT_SCHEMA,\n      render: (_args, value) => [{ type: 'text', text: noteText(value as NoteRecord) }],\n    },\n    async execute(args, _exec) {\n      const id = args.note_id as NoteId\n      const note = await notes.setPinned(id, args.pinned)\n      if (note === undefined) throw new Error(`note ${id} not found`)\n      return note\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: TOOL_DELETE,\n    description: 'Delete one sticky note. Deleting a note the user wrote themselves asks them for confirmation first; without an approval channel only the agent\\'s own notes can be deleted.',\n    parameters: {\n      note_id: { type: 'string', required: true, description: 'The note id from notes_list.' },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          deleted: { type: 'boolean', required: true },\n          id: { type: 'string', required: true },\n        },\n      },\n      render: (_args, value) => [{\n        type: 'text',\n        text: value.deleted ? `note ${value.id} deleted` : `note ${value.id} not found`,\n      }],\n    },\n    async execute(args, exec) {\n      const id = args.note_id as NoteId\n      const target = noteById(ctx, id)\n      if (target?.origin === 'user') await requestNoteConsent(ctx, exec, `delete your note \"${noteLabel(target)}\"`)\n      const deleted = await notes.delete(id)\n      return { deleted, id }\n    },\n  }))\n\n  /* ----- 任务工具 ----- */\n\n  ctx.tools.register(defineTool({\n    name: TOOL_TASK_SET_STATUS,\n    description:\n      'Set a task note\\'s lane status to \"running\" (the ONLY value this tool accepts). ' +\n      'Protocol: at the start of a run, assert \"running\" before doing the work — this is optional ' +\n      'since the host already grants \"running\" at dispatch and re-asserting it is a harmless no-op. ' +\n      'To end the run, do NOT use this tool: call notes_task_report instead (it writes the result ' +\n      'summary and settles the run to done/failed automatically). Only works while this note holds ' +\n      'an active execution lease for the calling session. ' +\n      'A dispatched task message starts with a ⇲ line carrying the note title (the formal ' +\n      'instruction sits at its end): read the note in full with ' +\n      'notes_get first (including lane.run.summary from a previous run), then do the work. ' +\n      'Only the lane status/result may be touched — never rewrite the note body, title, or color.',\n    parameters: {\n      note_id: { type: 'string', required: true, description: 'The task note id from notes_list.' },\n      status: { type: 'string', required: true, enum: [...TASK_STATUSES], description: 'Must be \"running\" (the only accepted value); done/failed go through notes_task_report.' },\n    },\n    output: {\n      schema: NOTE_OUTPUT_SCHEMA,\n      render: (_args, value) => [{ type: 'text', text: noteText(value as NoteRecord) }],\n    },\n    async execute(args, _exec) {\n      const id = args.note_id as NoteId\n      const status = args.status as TaskStatus\n      if (status !== 'running') {\n        throw new Error('任务状态变更请用执行中的 report 结束：set_status 仅允许置为 running')\n      }\n      const note = await notes.setTaskStatus(id, status)\n      if (note === undefined) throw new Error(`task note ${id} not found or has no lane`)\n      return note\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: TOOL_TASK_REPORT,\n    description:\n      'End a task run and record its result. Writes the run summary, sets status to \"done\" ' +\n      '(ok=true) or \"failed\" (ok=false), and releases the execution lease (after which another ' +\n      'notes_task_* call is rejected until the task is executed again). Protocol: read the task ' +\n      'note in full with notes_get first, work on it, then report ok=true + summary on success or ' +\n      'ok=false + reason on failure. Only the lane status/result may be touched — never rewrite ' +\n      'the note body, title, or color.',\n    parameters: {\n      note_id: { type: 'string', required: true, description: 'The task note id from notes_list.' },\n      ok: { type: 'boolean', required: true, description: 'true if the task succeeded, false if it failed.' },\n      summary: { type: 'string', required: true, description: 'Short markdown summary of the result, or the failure reason.' },\n    },\n    output: {\n      schema: NOTE_OUTPUT_SCHEMA,\n      render: (_args, value) => [{ type: 'text', text: noteText(value as NoteRecord) }],\n    },\n    async execute(args, _exec) {\n      const id = args.note_id as NoteId\n      const note = await notes.settleTaskRun(id, args.ok, args.summary)\n      if (note === undefined) throw new Error(`task note ${id} not found or has no lane`)\n      return note\n    },\n  }))\n\n  ctx.tools.guard((exec) => notesDeleteGuard(ctx, exec))\n\n  ctx.tools.guard((exec) => notesTaskGuard(ctx, exec))\n\n}\n\n"
