      "path": "packages/plugin-notes/src/webdav-backup.ts",
      "content": "/**\n * plugin-notes WebDAV 备份引擎（host 侧）。网络操作全部在此：浏览器 client 不\n * 直连 WebDAV（避开 CORS），只经 notes/webdav* remote 端点触发与查询。\n *\n * 职责：\n * - 配置读取（插件 Config 的 volatile 引用，由注入的读取点现取；缺省已合并）与有效性检查；\n * - 上推：整域序列化为带 schema 版本的 JSON → PUT 到 {url}{path}notes-*.json，\n *   HTTP Basic + HTTPS；成功后按 keep 清理最旧快照；\n * - watermark：meta 记已传最大 updatedAt，自动检查只在「到期且确有变更」时上传\n *   （省 WebDAV 流量）；手动/配置保存后的立即备份恒上传一次（验证连通）；\n * - 恢复：先自动上推当前快照（保险）→ GET 校验 payload → 全量重建便签；\n * - meta 状态（上次备份/恢复时间结果）落 notes_webdav 域，供设置弹窗展示。\n *\n * 失败隔离：一切网络/配置错误都转成结构化 { ok:false, reason } 并记入 meta，\n * 绝不抛出到调用方（remote 端点与定时循环都安全）。\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { KvTable } from '@deepseek-ai/dsh-storage-domain'\nimport type { NotesWebdavConfig } from './types.ts'\nimport type {\n  WebdavBackupResult,\n  WebdavListResult,\n  WebdavRestoreResult,\n  WebdavStatus,\n} from './types.ts'\nimport type { NoteRecord } from './types.ts'\nimport type { WebdavMeta } from './webdav-domain.ts'\nimport { emptyWebdavMeta, WEBDAV_META_KEY } from './webdav-domain.ts'\nimport {\n  backupFileName,\n  buildBackupPayload,\n  compareSnapshotNamesDesc,\n  uniqueBackupName,\n  filterBackupFiles,\n  isBackupFileName,\n  maxUpdatedAt,\n  parseHrefs,\n  selectPruneNames,\n  shouldUpload,\n  validateBackupPayload,\n} from './webdav-core.ts'\n\n/** 单个 WebDAV 请求超时。 */\nconst REQUEST_TIMEOUT_MS = 20_000\n\nexport interface WebdavEngineOptions {\n  /** 当前全部便签（含归档；恢复前自动备份需要全量）。 */\n  readonly listNotes: () => readonly NoteRecord[]\n  /** 全量重建便签（仅恢复流程使用；host 可信，跳过 origin guard）。 */\n  readonly replaceAll: (notes: readonly NoteRecord[]) => Promise<void>\n  /** notes_webdav 域 meta 表。 */\n  readonly metaTable: KvTable<string, WebdavMeta>\n  /**\n   * 读当前 WebDAV 配置（缺省已合并）。dsh 0.1.7 起配置是插件 Config 的 volatile\n   * 引用（settings 表单写它），由 index.ts 注入本读取点 —— 每次现取即最新值，\n   * 改配置立即生效；读取抛错时调用方按「配置不可用」降级。\n   */\n  readonly readConfig: () => NotesWebdavConfig\n}\n\n/** host 侧引擎给 NotesService remote 端点用的窄接口。 */\nexport interface WebdavRunner {\n  backupNow(): Promise<WebdavBackupResult>\n  listFiles(): Promise<WebdavListResult>\n  restore(target: string): Promise<WebdavRestoreResult>\n  status(): Promise<WebdavStatus>\n  /** 定时检查（由调度 interval 调用；内部消化一切错误）。 */\n  checkAutomatic(): Promise<void>\n}\n\nfunction normalizeDir(dir: string): string {\n  const trimmed = dir.trim().replace(/^\\/+/u, '').replace(/\\/+$/u, '')\n  return trimmed.length === 0 ? '' : trimmed + '/'\n}\n\nfunction normalizeBase(url: string): string {\n  const trimmed = url.trim()\n  return trimmed.endsWith('/') ? trimmed : trimmed + '/'\n}\n\nexport function createWebdavEngine(ctx: Context, options: WebdavEngineOptions): WebdavRunner {\n  /**\n   * 读当前 WebDAV 配置。配置是插件 Config 的 volatile 引用（由 index.ts 注入读取点），\n   * 同步可得、无需等服务；读取抛错时返回 null，各操作自行降级。\n   */\n  const currentConfig = async (): Promise<NotesWebdavConfig | null> => {\n    try {\n      return options.readConfig()\n    } catch {\n      return null\n    }\n  }\n\n  const metaGet = async (): Promise<WebdavMeta> => {\n    return options.metaTable.get(WEBDAV_META_KEY) ?? emptyWebdavMeta()\n  }\n  const metaPut = async (meta: WebdavMeta): Promise<void> => {\n    await options.metaTable.put(WEBDAV_META_KEY, meta)\n  }\n\n  /** 配置有效性：返回错误文案或 null。 */\n  const configError = (cfg: NotesWebdavConfig): string | null => {\n    if (!cfg.enabled) return 'WebDAV 未启用'\n    if (!/^https?:\\/\\//iu.test(cfg.url.trim())) return '服务器地址须为 http(s):// 完整 URL'\n    if (cfg.username.trim() === '') return '缺少账号'\n    if (cfg.password === '') return '缺少应用密码'\n    return null\n  }\n\n  const authHeader = (cfg: NotesWebdavConfig): string => {\n    const token = Buffer.from(`${cfg.username}:${cfg.password}`, 'utf8').toString('base64')\n    return `Basic ${token}`\n  }\n\n  async function dav(\n    cfg: NotesWebdavConfig,\n    method: string,\n    relative: string,\n    body?: string,\n    extraHeaders?: Record<string, string>,\n  ): Promise<Response> {\n    const controller = new AbortController()\n    const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS)\n    try {\n      return await fetch(normalizeBase(cfg.url) + relative, {\n        method,\n        headers: {\n          Authorization: authHeader(cfg),\n          ...(body !== undefined ? { 'Content-Type': 'application/json; charset=utf-8' } : {}),\n          ...extraHeaders,\n        },\n        body,\n        signal: controller.signal,\n      })\n    } finally {\n      clearTimeout(timer)\n    }\n  }\n\n  /** 确保远端目录存在：按 / 分段逐级 MKCOL；已存在（405/2xx）视为成功。 */\n  async function ensureRemoteDir(cfg: NotesWebdavConfig): Promise<void> {\n    const dir = normalizeDir(cfg.path)\n    if (dir === '') return\n    let acc = ''\n    for (const segment of dir.split('/').filter(Boolean)) {\n      acc += segment + '/'\n      const res = await dav(cfg, 'MKCOL', acc)\n      const ok = res.ok || res.status === 301 || res.status === 302 || res.status === 405\n      if (!ok) throw new Error(`创建远端目录失败（${acc}，HTTP ${res.status}）`)\n    }\n  }\n\n  /** 远端目录快照名列表（desc 时间序）；目录不存在时先建目录再列。 */\n  async function remoteSnapshotNames(cfg: NotesWebdavConfig): Promise<string[]> {\n    const dir = normalizeDir(cfg.path)\n    let res = await dav(cfg, 'PROPFIND', dir, undefined, { Depth: '1' })\n    if (!res.ok && (res.status === 404 || res.status === 409)) {\n      await ensureRemoteDir(cfg)\n      res = await dav(cfg, 'PROPFIND', dir, undefined, { Depth: '1' })\n    }\n    if (!res.ok) throw new Error(`列取远端目录失败（HTTP ${res.status}）`)\n    const text = await res.text()\n    const names = parseHrefs(text)\n      .map((href) => href.split('/').pop() ?? '')\n      .filter((name) => isBackupFileName(name))\n      .sort(compareSnapshotNamesDesc)\n    return names\n  }\n\n  async function putSnapshot(cfg: NotesWebdavConfig, notes: readonly NoteRecord[]): Promise<string> {\n    // 撞名去重：先列当前快照名，同一秒重复备份时用 -N 后缀，避免 PUT 覆盖旧快照。\n    const existing = new Set(await remoteSnapshotNames(cfg))\n    const name = uniqueBackupName(backupFileName(), existing)\n    const payload = buildBackupPayload(notes)\n    const dir = normalizeDir(cfg.path)\n    let res = await dav(cfg, 'PUT', dir + name, JSON.stringify(payload))\n    if (!res.ok && (res.status === 409 || res.status === 404)) {\n      await ensureRemoteDir(cfg)\n      res = await dav(cfg, 'PUT', dir + name, JSON.stringify(payload))\n    }\n    if (!res.ok) throw new Error(`上传备份失败（HTTP ${res.status}）`)\n    return name\n  }\n\n  async function pruneOld(cfg: NotesWebdavConfig, justUploaded: string): Promise<void> {\n    const keep = Math.max(1, Math.floor(cfg.keep) || 1)\n    const dir = normalizeDir(cfg.path)\n    const names = await remoteSnapshotNames(cfg)\n    const prune = selectPruneNames(names.filter((n) => n !== justUploaded), keep)\n    for (const name of prune) {\n      try {\n        const res = await dav(cfg, 'DELETE', dir + name)\n        if (!res.ok && res.status !== 404) {\n          ctx.logger.warn('[plugin-notes] webdav prune failed:', name, res.status)\n        }\n      } catch (error) {\n        ctx.logger.warn('[plugin-notes] webdav prune failed:', name, error)\n      }\n    }\n  }\n\n  /** 实际上传一份（无论有无变更；手动/改配置即试跑用）。失败落 meta 并返回结果。 */\n  async function backupNow(): Promise<WebdavBackupResult> {\n    const fail = async (reason: string): Promise<WebdavBackupResult> => {\n      const meta = await metaGet()\n      await metaPut({ ...meta, lastBackupAt: Date.now(), lastBackupOk: false, lastBackupError: reason })\n      return { ok: false, reason }\n    }\n    const webdav = await currentConfig()\n    if (webdav === null) return fail('无法读取 WebDAV 配置（settings 服务不可用）')\n    const invalid = configError(webdav)\n    if (invalid !== null) return fail(invalid)\n    try {\n      const notes = options.listNotes()\n      const name = await putSnapshot(webdav, notes)\n      await pruneOld(webdav, name)\n      const meta = await metaGet()\n      await metaPut({\n        ...meta,\n        lastBackupAt: Date.now(),\n        lastBackupName: name,\n        lastBackupOk: true,\n        lastBackupError: null,\n        watermark: maxUpdatedAt(notes),\n      })\n      return { ok: true, snapshot: name }\n    } catch (error) {\n      return fail(error instanceof Error ? error.message : String(error))\n    }\n  }\n\n  /** 定时自动检查：启用 + 到期（距上次成功 ≥ intervalMin）+ 确有变更才传。 */\n  async function checkAutomatic(): Promise<void> {\n    const webdav = await currentConfig()\n    if (webdav === null || configError(webdav) !== null) return\n    const meta = await metaGet()\n    const now = Date.now()\n    const due =\n      meta.lastBackupAt === null ||\n      now - meta.lastBackupAt >= Math.max(1, webdav.intervalMin) * 60_000\n    if (!due) return\n    const notes = options.listNotes()\n    if (!shouldUpload(maxUpdatedAt(notes), meta.watermark)) return\n    await backupNow()\n  }\n\n  /** 列远端快照（ok 分支返回 desc 时间序文件名）。 */\n  async function listFiles(): Promise<WebdavListResult> {\n    const webdav = await currentConfig()\n    if (webdav === null) return { ok: false, reason: '无法读取 WebDAV 配置（settings 服务不可用）' }\n    const invalid = configError(webdav)\n    if (invalid !== null) return { ok: false, reason: invalid }\n    try {\n      const names = await remoteSnapshotNames(webdav)\n      return { ok: true, files: names }\n    } catch (error) {\n      return { ok: false, reason: error instanceof Error ? error.message : String(error) }\n    }\n  }\n\n  /** 恢复：先自动备份当前 → 拉取校验 → 全量重建。target='latest' 取最新一份。 */\n  async function restore(target: string): Promise<WebdavRestoreResult> {\n    const webdav = await currentConfig()\n    if (webdav === null) return { ok: false, reason: '无法读取 WebDAV 配置（settings 服务不可用）' }\n    const invalid = configError(webdav)\n    if (invalid !== null) return { ok: false, reason: invalid }\n    try {\n      // 先解析目标文件名，再做安全备份：'latest' 取的是「恢复动作发生前」的\n      // 最近一份——若先备份再解析，latest 会指向刚生成的安全副本（=当前状态）。\n      const files = await remoteSnapshotNames(webdav)\n      if (files.length === 0) return { ok: false, reason: '远端没有可用快照' }\n      const name = target === 'latest' ? files[0]! : files.find((f) => f === target)\n      if (name === undefined) return { ok: false, reason: `找不到快照 ${target}` }\n\n      // 保险：先把当前便签推一份，失败即中止（避免覆盖后无备份）。\n      const safety = await backupNow()\n      if (!safety.ok) return { ok: false, reason: `恢复前自动备份失败：${safety.reason}` }\n\n      const dir = normalizeDir(webdav.path)\n      const res = await dav(webdav, 'GET', dir + name)\n      if (!res.ok) throw new Error(`下载快照失败（HTTP ${res.status}）`)\n      const raw = JSON.parse(await res.text()) as unknown\n      const payload = validateBackupPayload(raw)\n      const restoredNotes = payload.notes\n      await options.replaceAll(restoredNotes)\n\n      const meta = await metaGet()\n      await metaPut({\n        ...meta,\n        lastRestoreAt: Date.now(),\n        lastRestoreName: name,\n        lastRestoreOk: true,\n        watermark: maxUpdatedAt(restoredNotes),\n      })\n      return { ok: true, restored: restoredNotes.length, from: name }\n    } catch (error) {\n      const message = error instanceof Error ? error.message : String(error)\n      const meta = await metaGet()\n      await metaPut({ ...meta, lastRestoreAt: Date.now(), lastRestoreName: null, lastRestoreOk: false })\n      return { ok: false, reason: message }\n    }\n  }\n\n  /** 引擎状态快照（配置 enabled + meta 最近结果）。 */\n  async function status(): Promise<WebdavStatus> {\n    const webdav = await currentConfig()\n    const meta = await metaGet()\n    return {\n      enabled: webdav?.enabled ?? false,\n      lastBackupAt: meta.lastBackupAt,\n      lastBackupOk: meta.lastBackupOk,\n      lastBackupError: meta.lastBackupError,\n      lastBackupName: meta.lastBackupName,\n      lastRestoreAt: meta.lastRestoreAt,\n      lastRestoreOk: meta.lastRestoreOk,\n      lastRestoreName: meta.lastRestoreName,\n    }\n  }\n\n  return { backupNow, listFiles, restore, status, checkAutomatic }\n}\n\n/** 兜底：过滤备份文件名（重新导出供外部需要时用，防误用原始列表）。 */\nexport { filterBackupFiles }"
    },
    {
      "path": "packages/plugin-notes/src/domain.ts",
      "content": "/**\n * notes storage domain 声明：identity、格式版本与 zod 记录 schema。\n * 数据持久化只走 ctx.storage（storage-json 后端）之上的 storage-domain，\n * 不自造持久化。\n */\n\nimport type { ZodType } from 'zod'\nimport { z } from 'zod'\nimport { defineDomain, domainTable } from '@deepseek-ai/dsh-storage-domain'\nimport { DEFAULT_NOTE_COLOR, NOTE_COLORS, NOTE_ORIGINS, normalizeNoteColor } from './types.ts'\nimport type { NoteId, NoteRecord } from './types.ts'\n\n/**\n * 任务状态枚举（与 types.ts 的 TaskStatus 保持同步）。写死字面量数组以防\n * domain ↔ types 出现 import 环；改动 types.ts 的 TaskStatus 时须同步此处。\n */\nconst NOTE_TASK_STATUSES = ['backlog', 'todo', 'running', 'done', 'failed'] as const\n\n/**\n * 定时形态枚举（与 types.ts 的 ScheduleMode 保持同步）。同上写死字面量数组，\n * 避免 domain ↔ types 的 import 环；改动 types.ts 时须同步此处。\n */\nconst NOTE_SCHEDULE_MODES = ['once', 'interval', 'daily', 'weekly', 'monthly'] as const\n\n/**\n * 便签记录 schema：存储边界校验（storage-domain 打开时全量校验）。\n * color 带默认值：旧记录（v1 无该字段）打开时不炸，解析即回填默认黄。\n * zod 的 brand 与自有 Branded<NoteId> 符号不互通，这里用形状收窄声明，\n * 运行时校验仍覆盖全部字段。\n */\nexport const noteRecordSchema = z.object({\n  id: z.string(),\n  title: z.string(),\n  text: z.string(),\n  pinned: z.boolean(),\n  // archived 带默认值：v1 旧记录（无该字段）打开时不炸，解析即回填 false。\n  archived: z.boolean().default(false),\n  // color 带默认值：旧记录（v1 无该字段）打开时不炸，解析即回填默认黄。\n  // preprocess 归一历史紫色（v1 曾含紫，任务泳道分类收敛后移除）→ 灰，防旧数据炸库。\n  color: z.preprocess(\n    (v) => normalizeNoteColor(v) ?? v,\n    z.enum(NOTE_COLORS).default(DEFAULT_NOTE_COLOR),\n  ),\n  // origin 带默认值：v1 旧记录（无该字段）打开时不炸，解析即回填 'user'。\n  origin: z.enum(NOTE_ORIGINS).default('user'),\n  // lane 可选（无默认、不回填）：存在即任务（进泳道），缺省 = 普通便签。\n  // 旧记录天然无该字段，解析不炸；status 用五状态字面量枚举，run 帧\n  // startedAt 必填、finishedAt/ok/summary 可选。\n  // agentPreset / model 是可选执行目标（M2）：缺省 = 宿主默认；同样 optional，\n  // 旧记录与新记录都能过。\n  lane: z\n    .object({\n      status: z.enum(NOTE_TASK_STATUSES),\n      run: z\n        .object({\n          startedAt: z.number(),\n          finishedAt: z.number().optional(),\n          ok: z.boolean().optional(),\n          summary: z.string().optional(),\n          // 发起方（旧记录无 → optional，视同 'user'）；见 types.ts NoteRun。\n          by: z.enum(['user', 'schedule']).optional(),\n        })\n        .optional(),\n      agentPreset: z.string().optional(),\n      model: z\n        .object({\n          provider: z.string(),\n          model: z.string(),\n          reasoningEffort: z.string().optional(),\n        })\n        .optional(),\n    })\n    .optional(),\n  // schedule 可选（无默认、不回填）：任务定时执行日程（仅任务便签有意义）。\n  // 旧记录天然无该字段，解析不炸；缺省 = 不定时。nextAt 为 host 计算的权威下次时刻\n  // （必填），其余触发参数按 mode 取用。旧数据里不存在的字段一律 optional。\n  schedule: z\n    .object({\n      enabled: z.boolean(),\n      mode: z.enum(NOTE_SCHEDULE_MODES),\n      at: z.number().optional(),\n      everyMin: z.number().optional(),\n      time: z.string().optional(),\n      weekdays: z.array(z.number()).optional(),\n      monthDay: z.number().optional(),\n      endAt: z.number().optional(),\n      nextAt: z.number(),\n      lastFiredAt: z.number().optional(),\n      lastResult: z.string().optional(),\n      // 错误边界计数（旧记录无 → optional；见 types.ts NoteSchedule）。\n      failureStreak: z.number().optional(),\n      runCount: z.number().optional(),\n    })\n    .optional(),\n  // workspace 可选（无默认、不回填）：任务执行工作区（绝对目录路径）。旧记录\n  // 天然无该字段，解析不炸；缺省 = 执行会被拒（任务必须有工作区，M1-4）。\n  workspace: z.string().optional(),\n  // dueAt 可选（无默认、不回填）：截止时刻（绝对 ms）。旧记录天然无该字段。\n  dueAt: z.number().optional(),\n  createdAt: z.number(),\n  updatedAt: z.number(),\n}) as unknown as ZodType<NoteRecord>\n\n/**\n * 执行租约记录：每张任务便签至多一条 active lease（key = noteId，随撤销即删，\n * 无状态机）。sessionId 为发起执行的会话标识；grantedAt 为授权时刻。\n */\nexport interface TaskLease {\n  readonly noteId: NoteId\n  readonly sessionId: string\n  readonly grantedAt: number\n}\n\n/**\n * 租约记录 schema：存储边界校验。noteId 在介质上是普通字符串，接口层才品牌化为\n * NoteId（与 noteRecordSchema 的 id 同款收窄）；zod 形状校验仍覆盖全部字段。\n */\nexport const taskLeaseSchema = z.object({\n  noteId: z.string(),\n  sessionId: z.string(),\n  grantedAt: z.number(),\n}) as unknown as ZodType<TaskLease>\n\n/**\n * notes 域：notes 与 leases 两张表，per-record 布局（每条记录一份文档，便于增删）。\n * 格式版本 1；介质版本不符会在 open 时拒绝。\n */\nexport const notesDomain = defineDomain({\n  name: 'notes',\n  version: 1,\n  layout: 'per-record',\n  tables: {\n    notes: domainTable<NoteId, NoteRecord>(noteRecordSchema),\n    leases: domainTable<NoteId, TaskLease>(taskLeaseSchema),\n  },\n})\n"
    },
    {
      "path": "packages/plugin-notes/src/client/views/notes-board/components/CalendarBoard.tsx",
      "content": "/**\n * 日历视图：月网格（周一起始）+ 选中日事项列表。\n * 事项两类：截止（蓝点，`dueAt`）与定时触发（绿点，`schedule.nextAt`）。\n * 点格子选日，点事项进编辑器；月份用 ‹ › 翻，右上「今天」回到当月当日。\n * 布局只有几何在 JSX，hover/选中态在 styles/notes-board.module.css。\n */\n\nimport type { NoteRecord } from '../../../../types.ts'\nimport { fmtMonthDay } from '../../../core/due-date.ts'\nimport { t } from '../../../core/theme-tokens.ts'\nimport { useCalendarBoard } from './useCalendarBoard.ts'\nimport { ChevronLeft, ChevronRight } from 'lucide-react'\nimport styles from '../../../styles/notes-board.module.css'\n\nexport interface CalendarBoardProps {\n  /** 已做颜色/搜索筛选的活动便签。 */\n  readonly notes: readonly NoteRecord[]\n  readonly onEdit: (note: NoteRecord) => void\n}\n\nconst DUE_COLOR = 'var(--dsw-alias-state-business-primary)'\nconst SCHEDULE_COLOR = 'var(--dsw-alias-state-success-primary)'\n\nexport function CalendarBoard(props: CalendarBoardProps): JSX.Element {\n  const cal = useCalendarBoard({ notes: props.notes, onEdit: props.onEdit })\n  const selectedDate = new Date(`${cal.selectedKey}T00:00:00`)\n\n  return (\n    <div style={rootStyle}>\n      <header style={headStyle}>\n        <span style={labelStyle}>{cal.label}</span>\n        <span style={countStyle}>{cal.monthEventCount} 天有事项</span>\n        <span style={{ flex: 1 }} />\n        <button type=\"button\" className={styles.calNavBtn} style={navBtnStyle} title=\"上一月\" aria-label=\"上一月\" onClick={cal.goPrev}>\n          <ChevronLeft size={15} />\n        </button>\n        <button type=\"button\" className={styles.calNavBtn} style={todayBtnStyle} onClick={cal.goToday}>\n          今天\n        </button>\n        <button type=\"button\" className={styles.calNavBtn} style={navBtnStyle} title=\"下一月\" aria-label=\"下一月\" onClick={cal.goNext}>\n          <ChevronRight size={15} />\n        </button>\n      </header>\n\n      <div style={weekRowStyle} aria-hidden=\"true\">\n        {cal.weekdays.map((day) => (\n          <span key={day} style={weekdayStyle}>\n            {day}\n          </span>\n        ))}\n      </div>\n\n      <div style={gridStyle} role=\"grid\" aria-label={`${cal.label}日历`}>\n        {cal.cells.map((cell) => {\n          const dayEvents = cal.eventsByDay.get(cell.key) ?? []\n          const kinds = [...new Set(dayEvents.map((event) => event.kind))]\n          const selected = cell.key === cal.selectedKey\n          return (\n            <button\n              key={cell.key}\n              type=\"button\"\n              role=\"gridcell\"\n              aria-selected={selected}\n              aria-label={`${fmtMonthDay(cell.ts)}${dayEvents.length > 0 ? `，${dayEvents.length} 项` : ''}`}\n              className={[styles.calCell, cell.today ? styles.calCellToday : '', selected ? styles.calCellSelected : ''].join(' ')}\n              style={{\n                ...cellStyle,\n                ...(cell.inMonth ? {} : { opacity: 0.38 }),\n                ...(cell.today ? { color: t.labelPrimary } : {}),\n              }}\n              onClick={() => cal.selectDay(cell.key)}\n            >\n              <span style={cellDayStyle}>{cell.day}</span>\n              <span style={dotsStyle}>\n                {kinds.slice(0, 3).map((kind) => (\n                  <i\n                    key={kind}\n                    style={{\n                      ...dotStyle,\n                      background: kind === 'due' ? DUE_COLOR : SCHEDULE_COLOR,\n                    }}\n                  />\n                ))}\n              </span>\n            </button>\n          )\n        })}\n      </div>\n\n      <section style={panelStyle} aria-label=\"当日事项\">\n        <header style={panelHeadStyle}>\n          <span style={{ fontWeight: 500 }}>\n            {fmtMonthDay(selectedDate.getTime())} 周{cal.weekdays[(selectedDate.getDay() + 6) % 7]}\n          </span>\n          <span style={countStyle}>{cal.selectedEvents.length} 项</span>\n        </header>\n        <ul style={eventListStyle}>\n          {cal.selectedEvents.length === 0 ? (\n            <li style={emptyStyle}>这天没有事项</li>\n          ) : (\n            cal.selectedEvents.map((event) => (\n              <li key={`${event.note.id}:${event.kind}`}>\n                <button\n                  type=\"button\"\n                  className={styles.calEventRow}\n                  style={eventRowStyle}\n                  onClick={() => cal.openNote(event.note)}\n                >\n                  <i\n                    style={{\n                      ...dotStyle,\n                      flex: 'none',\n                      background: event.kind === 'due' ? DUE_COLOR : SCHEDULE_COLOR,\n                    }}\n                  />\n                  <span style={eventKindStyle}>{event.kind === 'due' ? '截止' : '定时'}</span>\n                  <span style={eventTitleStyle} title={event.note.title}>\n                    {event.note.title || '（无标题）'}\n                  </span>\n                  <span style={eventTimeStyle}>\n                    {event.kind === 'due'\n                      ? '全天'\n                      : new Date(event.at).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })}\n                  </span>\n                </button>\n              </li>\n            ))\n          )}\n        </ul>\n      </section>\n    </div>\n  )\n}\n\n/* ---------- 样式（几何 + 令牌；hover/选中态在 notes-board.module.css） ---------- */\n\nconst rootStyle: React.CSSProperties = {\n  display: 'flex',\n  flexDirection: 'column',\n  height: '100%',\n  minHeight: 0,\n  gap: 8,\n}\nconst headStyle: React.CSSProperties = {\n  display: 'flex',\n  alignItems: 'center',\n  gap: 8,\n  flex: 'none',\n}\nconst labelStyle: React.CSSProperties = {\n  fontSize: 14,\n  fontWeight: 600,\n  color: t.labelPrimary,\n}\nconst countStyle: React.CSSProperties = {\n  fontSize: 12,\n  color: t.labelTertiary,\n}\nconst navBtnStyle: React.CSSProperties = {\n  display: 'inline-flex',\n  alignItems: 'center',\n  justifyContent: 'center',\n  width: 26,\n  height: 26,\n  padding: 0,\n  border: 'none',\n  borderRadius: 7,\n  color: t.labelSecondary,\n  cursor: 'pointer',\n}\nconst todayBtnStyle: React.CSSProperties = {\n  ...navBtnStyle,\n  width: 'auto',\n  padding: '0 10px',\n  fontSize: 12,\n  color: t.labelPrimary,\n  background: t.hoverBg,\n}\nconst weekRowStyle: React.CSSProperties = {\n  display: 'grid',\n  gridTemplateColumns: 'repeat(7, 1fr)',\n  gap: 4,\n  flex: 'none',\n}\nconst weekdayStyle: React.CSSProperties = {\n  textAlign: 'center',\n  fontSize: 11.5,\n  color: t.labelTertiary,\n  padding: '2px 0',\n}\nconst gridStyle: React.CSSProperties = {\n  display: 'grid',\n  gridTemplateColumns: 'repeat(7, 1fr)',\n  gridTemplateRows: 'repeat(6, minmax(42px, 1fr))',\n  gap: 4,\n  flex: 1,\n  minHeight: 0,\n}\nconst cellStyle: React.CSSProperties = {\n  display: 'flex',\n  flexDirection: 'column',\n  alignItems: 'flex-start',\n  justifyContent: 'space-between',\n  gap: 2,\n  padding: '5px 6px',\n  borderRadius: 8,\n  color: t.labelSecondary,\n  cursor: 'pointer',\n  minWidth: 0,\n  overflow: 'hidden',\n}\nconst cellDayStyle: React.CSSProperties = {\n  fontSize: 24,\n  lineHeight: 1.2,\n  fontWeight: 600,\n  fontVariantNumeric: 'tabular-nums',\n}\nconst dotsStyle: React.CSSProperties = {\n  display: 'inline-flex',\n  alignItems: 'center',\n  gap: 3,\n  minHeight: 5,\n}\nconst dotStyle: React.CSSProperties = {\n  width: 5,\n  height: 5,\n  borderRadius: 3,\n  display: 'inline-block',\n}\nconst panelStyle: React.CSSProperties = {\n  flex: 'none',\n  maxHeight: 168,\n  display: 'flex',\n  flexDirection: 'column',\n  gap: 6,\n  paddingTop: 8,\n  borderTop: `1px solid ${t.borderL1}`,\n  minHeight: 0,\n}\nconst panelHeadStyle: React.CSSProperties = {\n  display: 'flex',\n  alignItems: 'center',\n  gap: 8,\n  fontSize: 12.5,\n  color: t.labelPrimary,\n  flex: 'none',\n}\nconst eventListStyle: React.CSSProperties = {\n  margin: 0,\n  padding: 0,\n  listStyle: 'none',\n  display: 'flex',\n  flexDirection: 'column',\n  gap: 2,\n  overflowY: 'auto',\n  minHeight: 0,\n}\nconst eventRowStyle: React.CSSProperties = {\n  display: 'flex',\n  alignItems: 'center',\n  gap: 8,\n  width: '100%',\n  boxSizing: 'border-box',\n  padding: '6px 8px',\n  border: 'none',\n  borderRadius: 7,\n  color: t.labelPrimary,\n  fontSize: 12.5,\n  textAlign: 'left',\n  cursor: 'pointer',\n}\nconst eventKindStyle: React.CSSProperties = {\n  flex: 'none',\n  fontSize: 11,\n  color: t.labelTertiary,\n}\nconst eventTitleStyle: React.CSSProperties = {\n  flex: 1,\n  minWidth: 0,\n  overflow: 'hidden',\n  textOverflow: 'ellipsis',\n  whiteSpace: 'nowrap',\n}\nconst eventTimeStyle: React.CSSProperties = {\n  flex: 'none',\n  fontSize: 11.5,\n  color: t.labelTertiary,\n  fontVariantNumeric: 'tabular-nums',\n}\nconst emptyStyle: React.CSSProperties = {\n  padding: '14px 0',\n  textAlign: 'center',\n  fontSize: 12.5,\n  color: t.labelTertiary,\n}\n"
    }
